  'step-by-step-heading' => 'Քայլ առ քայլ ուղեցույց. Ինչպես սեղմել PDF-ը',
  'step-by-step-intro' => 'Ահա թե ինչպես կարող եք սեղմել PDF ֆայլերը օպտիմալ ձևով:',
  'step1-text' => 'Քայլ 1. Վերբեռնեք PDF ֆայլը՝ օգտագործելով վստահելի սեղմման գործիքի միջերես:',
  'step2-text' => 'Քայլ 2. Ընտրեք սեղմման մակարդակ, որը հավասարակշռում է ֆայլի չափը և տեսողական պարզությունը:',
  'step3-text' => 'Քայլ 3. Վերանայեք առկա տարբերակները և հաստատեք կարգավորումները նախքան մշակումը սկսելը:',
  'step4-text' => 'Քայլ 4. Նախադիտեք սեղմված փաստաթուղթը՝ տեքստային պատկերները և դասավորության որակը ստուգելու համար:',
  'step5-text' => 'Քայլ 5. Կարգավորեք սեղմման կարգավորումները, եթե որակը չի համապատասխանում ընթերցանության ակնկալիքներին:',
  'step6-text' => 'Քայլ 6. Ավարտեք գործընթացը, երբ նախադիտումը բավարարում է բովանդակության և հստակության կարիքները:',
  'step7-text' => 'Քայլ 7. Ներբեռնեք օպտիմիզացված PDF ֆայլը և ապահով պահեք այն համօգտագործելու համար:',
  'free-vs-paid-heading' => 'Անվճար ընդդեմ վճարովի PDF սեղմման գործիքներ',
